'AC-meta.governance-ratchet.10'; from __future__ import annotations; import ast; from pathlib import Path; import pytest; from common.meta.base.detector_runner import all_of, missing_fragments, requires, run_detectors; from common.meta.contract import CONTRACT as META_CONTRACT; from common.meta.extension.governance_detector import detect_governance; REPO_ROOT = Path(__file__).resolve().parents[2]; PROVIDERS = sorted(REPO_ROOT.glob('common/*/extension/governance_detector.py')); SEEDED_SHAPE = '\ndef _source(repo_root, relative): ...\nasync def _contains(repo_root, relative, fragments): ...\ndef _peek(path):\n    return path.read_text(encoding="utf-8")\ndef detect_governance(*, repo_root):\n    return [check(repo_root) for check in _CHECKS]\n'
def _shape_violations(source: str) -> list[str]: funcs = {node.name: node for node in ast.parse(source).body if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))}; findings = [f'defines {name}' for name in ('_source', '_contains') if name in funcs]; findings += [f'{name} calls read_text' for name, node in funcs.items() if any((isinstance(call, ast.Call) and getattr(call.func, 'attr', '') == 'read_text' for call in ast.walk(node)))]; calls = [node for node in funcs['detect_governance'].body if not (isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant))]; findings.append('detect_governance is not one run_detectors call') if not (len(calls) == 1 and isinstance(calls[0], ast.Return) and isinstance(calls[0].value, ast.Call) and (getattr(calls[0].value.func, 'id', '') == 'run_detectors')) else None; return findings
def test_AC_meta_governance_ratchet_10_providers_delegate_to_one_runner() -> None:
    'AC-meta.governance-ratchet.10'; assert [path.parts[-3] for path in PROVIDERS] == ['extraction', 'meta', 'reconciliation', 'reporting']
    for path in PROVIDERS: assert _shape_violations(path.read_text(encoding='utf-8')) == [], path
    assert _shape_violations(SEEDED_SHAPE) == ['defines _source', 'defines _contains', '_peek calls read_text', 'detect_governance is not one run_detectors call']; 'AC-meta.governance-ratchet.10'; 'AC-meta.governance-ratchet.10'
    with pytest.raises(ValueError, match='no checks'): run_detectors('demo', {})
    with pytest.raises(ValueError, match='at least one fragment'): requires('a.py')
    with pytest.raises(ValueError, match='at least one check'): all_of()
def test_AC_meta_governance_ratchet_10_runner_observations_and_exception_policy() -> None:
    'AC-meta.governance-ratchet.10'
    def broken(_: object) -> list[str]: raise FileNotFoundError('gone.py')
    def bug(_: object) -> list[str]: raise TypeError('defect')
    checks = {'holds': lambda _: [], 'breaks': lambda arg: [f'bad {arg}', 'worse']}; assert run_detectors('demo', checks, 'ctx') == [{'guarantee_id': 'demo/holds', 'current': 0, 'target': 0, 'findings': []}, {'guarantee_id': 'demo/breaks', 'current': 2, 'target': 0, 'findings': ['bad ctx', 'worse']}]; [read] = run_detectors('demo', {'read': broken}, None); assert read['findings'] == ['read: check failed (FileNotFoundError): gone.py']
    with pytest.raises(TypeError): run_detectors('demo', {'bug': bug}, None)
    [wide] = run_detectors('demo', {'bug': bug}, None, catch=(Exception,)); assert wide['findings'] == ['bug: check failed (TypeError): defect']
def test_AC_meta_governance_ratchet_10_missing_fragments_ignores_layout_only(tmp_path: Path) -> None: 'AC-meta.governance-ratchet.10'; (tmp_path / 'ok.py').write_text('value = (\n    1,\n    2,\n)\n', encoding='utf-8'); (tmp_path / 'broken.py').write_text('def broken(:\n', encoding='utf-8'); (tmp_path / 'notes.md').write_text('def broken(:\n', encoding='utf-8'); check = all_of(requires('ok.py', 'value = ( 1, 2, )'), requires('notes.md', 'def broken(:')); assert check(tmp_path) == []; assert requires('ok.py', 'value = 3')(tmp_path) == ['ok.py: missing value = 3']; assert missing_fragments(tmp_path, 'gone.py', ('x',)) == ['gone.py: file does not exist']; [syntax] = requires('broken.py', 'def broken(:')(tmp_path); assert syntax.startswith('broken.py: syntax error (SyntaxError)'); 'AC-meta.governance-ratchet.10'; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); 'AC-meta.governance-ratchet.10'; _m2_expected = {f'meta/{_m2_guarantee.id}' for _m2_initiative in META_CONTRACT.governance if _m2_initiative.id == 'app-and-frontend-governance' for _m2_guarantee in _m2_initiative.guarantees}; assert {_m2_item['guarantee_id'] for _m2_item in detect_governance(repo_root=REPO_ROOT)} == _m2_expected; _m2_red = {_m2_item['guarantee_id'] for _m2_item in detect_governance(repo_root=_m2_tmp) if _m2_item['current'] > 0 and _m2_item['findings']}; assert _m2_red == {'meta/python-boundary-denominator', 'meta/frontend-export-denominator', 'meta/operation-consumer-truth', 'meta/non-vacuity', 'meta/governance-integration'}
